149	/**
150	 * Parse and validate required environment variables, initialize Octokit.
151	 * Throws if GH_TOKEN, REPO, PR_NUMBER, or REVIEWER are missing or invalid.
152	 */
153	export function parseRepoEnv(): RepoEnv {
154	  const token = process.env.GH_TOKEN;
155	  const repo = process.env.REPO;
156	  const prNumber = process.env.PR_NUMBER;
157	  const reviewer = process.env.REVIEWER;
158	
159	  if (!token || !repo || !prNumber || !reviewer) {
160	    throw new Error("Missing required environment variables: GH_TOKEN, REPO, PR_NUMBER, REVIEWER");
161	  }
162	
163	  const [owner, repoName] = repo.split("/");
164	  if (!owner || !repoName) {
165	    throw new Error(`Invalid REPO format: ${repo}. Expected owner/repo`);
166	  }
167	
168	  return {
169	    octokit: createOctokit(token),
170	    owner,
171	    repoName,
172	    pullNumber: Number(prNumber),
173	    reviewer,
174	  };
175	}
176	
177	/** Flatten a GraphQL review-thread node into a {@link ReviewThread}. */
178	function mapThreadNode(node: ReviewThreadNode): ReviewThread {
179	  return {
180	    id: node.id,
181	    path: node.path,
182	    line: node.line,
183	    isOutdated: node.isOutdated,
184	    isResolved: node.isResolved,
185	    firstCommentAuthor: node.comments.nodes[0]?.author?.login ?? null,
186	    firstCommentBody: node.comments.nodes[0]?.body ?? "",
187	    firstCommentReviewId: node.comments.nodes[0]?.pullRequestReview?.id ?? null,
188	  };
189	}
190	
191	/** Fetch a single page of review threads. Explicit return type pins inference. */
192	async function fetchReviewThreadPage(
193	  octokit: Octokit,
194	  owner: string,
195	  repo: string,
196	  pullNumber: number,
197	  cursor: string | null
198	): Promise<ReviewThreadsResponse> {
199	  const query = `
200	    query($owner: String!, $repo: String!, $number: Int!, $cursor: String) {
201	      repository(owner: $owner, name: $repo) {
202	        pullRequest(number: $number) {
203	          reviewThreads(first: 100, after: $cursor) {
204	            nodes {
205	              id
206	              path
207	              line
208	              isOutdated
209	              isResolved
210	              comments(first: 1) {
211	                nodes {
212	                  author { login }
213	                  body
214	                  pullRequestReview { id }
215	                }
216	              }
217	            }
218	            pageInfo { hasNextPage endCursor }
219	          }
220	        }
221	      }
222	    }
223	  `;
224	
225	  return octokit.graphql<ReviewThreadsResponse>(query, { owner, repo, number: pullNumber, cursor });
226	}
227	
228	/**
229	 * Fetch all review threads for a PR via GraphQL, paginating past the 100-node
230	 * page so long-lived PRs don't silently drop threads from resolution logic.
231	 */
232	export async function fetchReviewThreads(
233	  octokit: Octokit,
234	  owner: string,
235	  repo: string,
236	  pullNumber: number
237	): Promise<ReviewThread[]> {
238	  const threads: ReviewThread[] = [];
239	  let cursor: string | null = null;
240	
241	  for (;;) {
242	    const page: ReviewThreadsResponse = await fetchReviewThreadPage(
243	      octokit,
244	      owner,
245	      repo,
246	      pullNumber,
247	      cursor
248	    );
249	    const { reviewThreads } = page.repository.pullRequest;
250	    threads.push(...reviewThreads.nodes.map(mapThreadNode));
251	    if (!reviewThreads.pageInfo.hasNextPage) break;
252	    cursor = reviewThreads.pageInfo.endCursor;
253	  }
254	
255	  return threads;
256	}
257	
258	/**
259	 * Resolve a single review thread by its GraphQL node ID.
260	 */
261	export async function resolveThread(octokit: Octokit, threadId: string): Promise<void> {
262	  await octokit.graphql(
263	    `
264	      mutation($threadId: ID!) {
265	        resolveReviewThread(input: { threadId: $threadId }) {
266	          thread { isResolved }
267	        }
268	      }
269	    `,
270	    { threadId }
271	  );
272	}
273	
274	/**
275	 * Unresolve a single review thread by its GraphQL node ID.
276	 * Used to reopen threads that GitHub auto-resolves on APPROVE reviews.
277	 */
278	export async function unresolveThread(octokit: Octokit, threadId: string): Promise<void> {
279	  await octokit.graphql(
280	    `
281	      mutation($threadId: ID!) {
282	        unresolveReviewThread(input: { threadId: $threadId }) {
283	          thread { isResolved }
284	        }
285	      }
286	    `,
287	    { threadId }
288	  );
289	}
290	
291	/**
292	 * Delete all pending reviews for a PR to avoid GitHub's single-pending-review limit.
293	 */
294	export async function deletePendingReviews(
295	  octokit: Octokit,
296	  owner: string,
297	  repo: string,
298	  pullNumber: number
299	): Promise<void> {
300	  const { data: reviews } = await octokit.rest.pulls.listReviews({
301	    owner,
302	    repo,
303	    pull_number: pullNumber,
304	  });
305	
306	  const pendingReviews = reviews.filter((r) => r.state === "PENDING");
307	
308	  for (const review of pendingReviews) {
309	    console.log(`Deleting pending review ${review.id}...`);
310	    await octokit.rest.pulls.deletePendingReview({
311	      owner,
312	      repo,
313	      pull_number: pullNumber,
314	      review_id: review.id,
315	    });
316	  }
317	}
318	
319	/**
320	 * Read Claude's plain text result from the execution output file.
321	 * Falls back gracefully: returns null if file is missing, unreadable, or lacks a result message.
322	 *
323	 * @param filePath - Path to the execution output JSON file
324	 * @see https://docs.anthropic.com/en/docs/agent-sdk/typescript - SDKResultMessage
325	 */
326	export async function readExecutionResult(filePath: string | undefined): Promise<string | null> {
327	  if (!filePath) {
328	    return null;
329	  }
330	
331	  try {
332	    const data: unknown = await Bun.file(filePath).json();
333	    const messages = Array.isArray(data) ? data : [data];
334	    const resultMessage = messages.findLast(
335	      (m) => typeof m === "object" && m !== null && (m as Record<string, unknown>).type === "result"
336	    ) as Record<string, unknown> | undefined;
337	    const result = resultMessage?.result;
338	    return typeof result === "string" ? result : null;
339	  } catch {
340	    return null;
341	  }
342	}
343	
344	/**
345	 * Check if the bot already submitted a review on the current PR head commit.
346	 * Detects reviews submitted during Claude's execution via MCP tools when structured output is missing.
347	 *
348	 * @param headSha - Current PR head commit SHA for commit-level matching
349	 */
350	export async function hasRecentBotReview(
351	  octokit: Octokit,
352	  owner: string,
353	  repo: string,
354	  pullNumber: number,
355	  reviewer: string,
356	  headSha?: string
357	): Promise<boolean> {
358	  const { data: reviews } = await octokit.rest.pulls.listReviews({
359	    owner,
360	    repo,
361	    pull_number: pullNumber,
362	  });
363	
364	  const lastBotReview = reviews
365	    .filter((r) => r.user?.login === reviewer && r.state !== "PENDING")
366	    .at(-1);
367	
368	  if (!lastBotReview) {
369	    return false;
370	  }
371	
372	  if (headSha) {
373	    return lastBotReview.commit_id === headSha;
374	  }
375	
376	  return true;
377	}
378	
379	/**
380	 * Check if the bot already replied to a specific comment.
381	 * Detects replies submitted during Claude's execution via MCP tools when structured output is missing.
382	 */
383	export async function hasRecentBotReply(
384	  octokit: Octokit,
385	  owner: string,
386	  repo: string,
387	  pullNumber: number,
388	  reviewer: string,
389	  commentId?: string,
390	  commentPath?: string
391	): Promise<boolean> {
392	  const since = new Date(Date.now() - 15 * 60 * 1000).toISOString();
393	
394	  if (commentPath && commentId) {
395	    const { data: comments } = await octokit.rest.pulls.listReviewComments({
396	      owner,
397	      repo,
398	      pull_number: pullNumber,
399	      since,
400	    });
401	    return comments.some(
402	      (c) => c.in_reply_to_id === Number(commentId) && c.user?.login === reviewer
403	    );
404	  }
405	
406	  const { data: comments } = await octokit.rest.issues.listComments({
407	    owner,
408	    repo,
409	    issue_number: pullNumber,
410	    since,
411	  });
412	  return comments.some((c) => c.user?.login === reviewer);
413	}
