  if (/(^|\/)(dist|build|vendor|node_modules|\.repomix)\//.test(path)) return true;
  if (/(^|\/)(bun\.lock|bun\.lockb|package-lock\.json|yarn\.lock|pnpm-lock\.yaml)$/.test(path)) {
