      threadsTruncated: z.boolean(),
    })
    .strict(),
  unavailableSchema,
]);

const deltaSchema = z.discriminatedUnion("available", [
  z
    .object({
      available: z.literal(true),
      files: z.array(z.string()).max(bundleBounds.maxDeltaFiles),
      commitCount: z.number().int().nonnegative(),
