  .object({
    builder_ms: z.number().int().nonnegative(),
    request_count: z.number().int().nonnegative(),
    bundle_bytes: z.number().int().nonnegative(),
    diff_bytes: z.number().int().nonnegative(),
    truncated: z.boolean(),
    sections_unavailable: z.number().int().nonnegative(),
